// spec: specs/matchmaker.md (раздел 1.2)
// seed: tests/seed.free.spec.ts
// Расхождения плана с живой страницей (19.11.2026):
//  - разделитель в подписи FAQ — «·» (в плане «•»); принимаем оба;
//  - подпись «מה אם לא נמצא? · מי רואה את השאלון?» остаётся в кнопке и при раскрытом списке (скрываются только ответы/вопросы-строки);
//  - у кнопки FAQ нет aria-expanded — состояние проверяем по видимости ответов.
// Тексты ответов написаны программистом и ждут согласования с клиентом (могут измениться).
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/free-r13.json'),
  colorScheme: 'dark',
});

test.describe('שדכנית אישית (#3a3cb9 #58614c)', () => {
  test('FAQ раскрывается и сворачивается @iphone @prod-safe', async ({ page }) => {
    await page.goto('/settings');
    await page.getByRole('button', { name: 'השידוך שלי' }).click();
    await expect(page).toHaveURL(/\/matchmaker$/);

    const faq = page.getByRole('button', { name: /^שאלות נפוצות/ });
    const caption = faq.getByText(/^מה אם לא נמצא\?\s*[·•]\s*מי רואה את השאלון\?$/);
    const answerLost = page.getByText(/עד 3 חודשים\)/);
    const answerPrivacy = page.getByText(/רק השדכנית שמלווה אותך וצוות Magnet/);

    await expect(caption).toBeVisible();
    await expect(answerLost).toBeHidden();
    await expect(answerPrivacy).toBeHidden();

    // 1. Нажать «שאלות נפוצות»
    await faq.click();
    await expect(page.getByText('מה אם לא נמצא?', { exact: true })).toBeVisible();
    await expect(page.getByText('מי רואה את השאלון?', { exact: true })).toBeVisible();
    await expect(answerLost).toBeVisible();
    await expect(answerPrivacy).toBeVisible();

    // 2. Нажать ещё раз
    await faq.click();
    await expect(answerLost).toBeHidden();
    await expect(answerPrivacy).toBeHidden();
    await expect(caption).toBeVisible();
  });
});
